#include "optimizer_loop_internal.h"

/**
 * @brief Check whether the operand is available unchanged before the loop.
 *
 * @param blocks Blocks in the loop region.
 * @param count Number of blocks in the region.
 * @param operand Operand to examine or rewrite.
 * @return True if the operand does not depend on a definition inside the loop.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Hoist safe operations and stable initialized loads from simple
// loops.
static bool invariant_operand(IrBlock* const* blocks,
                              size_t count,
                              IrOperand operand) {
  if (operand.type != IR_OP_VALUE)
    return true;

  for (size_t b = 0; b < count; b++)
    for (size_t i = 0; i < blocks[b]->instructions.count; i++)
      if (blocks[b]->instructions.data[i].result == operand.value.id)
        return false;

  return true;
}

/**
 * @brief Check whether the block overwrites the given slot.
 *
 * @param block Block to inspect or update.
 * @param slot Stack slot holding the induction variable or value under
 * analysis.
 * @return True if the block contains a store to the slot.
 */
static bool stores_slot(const IrBlock* block, IrStackSlotId slot) {
  for (size_t i = 0; i < block->instructions.count; i++) {
    const IrInstruction* inst = &block->instructions.data[i];

    if (inst->type == IR_INST_STORE && inst->operands.store.target == slot)
      return true;
  }

  return false;
}

/**
 * @brief Check whether a slot is initialized before entry and unchanged inside
 * the loop.
 *
 * @param fn Function containing the loop.
 * @param pre Preheader that can supply the initial slot value.
 * @param blocks Blocks in the loop region.
 * @param count Number of blocks in the region.
 * @param slot Stack slot holding the induction variable or value under
 * analysis.
 * @return True if the slot can be read safely in the preheader and remains
 * unchanged.
 */
static bool invariant_load(const IrFunction* fn,
                           const IrBlock* pre,
                           IrBlock* const* blocks,
                           size_t count,
                           IrStackSlotId slot) {
  if (slot >= fn->parameter_count && !stores_slot(pre, slot))
    return false;

  for (size_t b = 0; b < count; b++)
    if (stores_slot(blocks[b], slot))
      return false;

  return true;
}

void optimizer_loop_hoist_simple_loop(Ctx* ctx,
                                      const IrFunction* fn,
                                      IrBlock* pre,
                                      IrBlock* const* blocks,
                                      size_t count) {
  // Only move operations safe to execute even if the loop body never runs.
  for (size_t b = 0; b < count; b++) {
    IrInstructionArray* from = &blocks[b]->instructions;

    for (size_t i = 0; i < from->count;) {
      IrInstruction inst = from->data[i];
      IrOperand* operands[2];
      size_t operand_count = optimizer_loop_operands_of(&inst, operands);
      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Ok, implement all, remove things made redundant by this change"
      // Changes: Treat string length as a pure unary operation during loop motion.
      bool safe = inst.type == IR_INST_STR_LEN || inst.type == IR_INST_NOT ||
                  inst.type == IR_INST_INT2DOUBLE ||
                  (inst.type >= IR_INST_EQ && inst.type <= IR_INST_GE);

      if (inst.type == IR_INST_LOAD) {
        safe =
            invariant_load(fn, pre, blocks, count, inst.operands.load.source);
      }

      for (size_t j = 0; j < operand_count && safe; j++)
        safe = invariant_operand(blocks, count, *operands[j]);

      if (!safe) {
        i++;
        continue;
      }

      array_append(ctx, &pre->instructions, inst);
      array_remove(ctx, from, i);
    }
  }
}
